    public Result searchForOwner(List<String> kbIds, String query, Integer ownerId, int limit) {
        return result(() -> {
            List<String> ids = requireReadableBaseIdsForOwner(kbIds, ownerId);
            if (query == null || query.isBlank() || query.length() > 2000) throw invalid("检索问题不能为空且不能超过 2000 字");
            if (RagBm25.tokenize(query).isEmpty()) return new RagSearchResponse(List.of(), "bm25", "问题缺少可检索的实词，请补充具体概念。");
            int top = Math.max(1, Math.min(20, limit));
            String placeholders = String.join(",", java.util.Collections.nCopies(ids.size(), "?"));
            List<Map<String,Object>> rows = jdbc.queryForList("SELECT c.*,d.title FROM native_rag_chunk c JOIN native_rag_document d ON c.document_id=d.id WHERE c.index_version=d.active_index_version AND c.kb_id IN (" + placeholders + ") ORDER BY c.id LIMIT " + (MAX_SEARCH_CHUNKS + 1), ids.toArray());
            if (rows.size() > MAX_SEARCH_CHUNKS) throw invalid("检索范围超过 2 万片段，请缩小知识库范围");
            double[] lexical = RagBm25.score(query, rows.stream().map(row -> text(row, "content")).toList());
            String mode = "bm25";
            String warning = "当前使用 BM25 关键词检索；未启用语义向量检索。";
            double[] queryVector = null;
            String model = embeddings.fingerprint();
            boolean vectorAvailable = rows.stream().anyMatch(row -> model.equals(row.get("vector_model")) && row.get("vector_json") != null);
            if (embeddings.isConfigured() && vectorAvailable) {
                try {
                    queryVector = embeddings.embed(List.of(query)).getFirst();
                    mode = "hybrid";
                    warning = rows.stream().allMatch(row -> model.equals(row.get("vector_model")) && row.get("vector_json") != null)
                            ? "" : "部分文档没有当前模型的向量，仅对其进行关键词检索；请由所有者重新建立向量索引。";
                } catch (IllegalStateException e) { warning = "向量服务不可用，已明确降级为 BM25 关键词检索。"; }
            } else if (embeddings.isConfigured()) warning = "所选文档没有当前模型的向量，实际使用 BM25 关键词检索；请由所有者重新建立向量索引。";
            else if (embeddings.isRequested()) warning = "向量配置不完整，实际使用 BM25 关键词检索。";
            double[] similarities = new double[rows.size()];
            java.util.Arrays.fill(similarities, Double.NaN);
            int usableVectors = 0;
            if (queryVector != null) {
                for (int i = 0; i < rows.size(); i++) {
                    var row = rows.get(i);
                    if (!model.equals(row.get("vector_model"))) continue;
                    similarities[i] = cosine(queryVector, row.get("vector_json"));
                    if (Double.isFinite(similarities[i])) usableVectors++;
                }
                if (usableVectors == 0) {
                    queryVector = null;
                    mode = "bm25";
                    warning = "持久化向量与当前查询向量不兼容，实际使用 BM25 关键词检索；请重新建立向量索引。";
                }
            }
            List<RagSearchHit> hits = new ArrayList<>();
            for (int i = 0; i < rows.size(); i++) {
                var row = rows.get(i);
                double similarity = similarities[i];
                if (lexical[i] <= 0 && (!Double.isFinite(similarity) || similarity < 0.62)) continue;
                double score = queryVector == null ? lexical[i] : 0.7 * lexical[i] / (1 + lexical[i]) + 0.3 * (Double.isFinite(similarity) ? Math.max(0, similarity) : 0);
                hits.add(hit(row, score));
            }
            hits.sort(Comparator.comparingDouble(RagSearchHit::score).reversed().thenComparing(RagSearchHit::chunkId));
            List<RagSearchHit> numbered = new ArrayList<>();
            for (int i = 0; i < Math.min(top, hits.size()); i++) {
                var h = hits.get(i);
                numbered.add(withVisuals(new RagSearchHit(h.chunkId(), h.documentId(), h.kbId(), h.title(), h.content(), h.page(), h.ordinal(), h.score(), "[" + (i + 1) + "]"),ownerId));
            }
            requireReadableBaseIdsForOwner(ids,ownerId);
            if(numbered.stream().anyMatch(hit->!com.cupk.aiacademy.rag.formula.FormulaText.analyze(hit.content()).blocks().isEmpty()))
                warning += " 检索结果包含公式，请对照原页核验；可排版不代表识别准确。";
            return new RagSearchResponse(List.copyOf(numbered), mode, warning);
        });
    }

    private List<Map<String,Object>> rowsForDocument(String id) {
        return jdbc.queryForList("SELECT c.*,d.title FROM native_rag_chunk c JOIN native_rag_document d ON c.document_id=d.id WHERE c.document_id=? AND c.index_version=d.active_index_version ORDER BY c.ordinal_number", id);
    }

